using System.Security.Claims;
using Hexalith.FrontComposer.Shell.Services.Auth;
using Hexalith.FrontComposer.Contracts.Rendering;
using Hexalith.Tenants.UI.Services.Configuration;
using Microsoft.AspNetCore.Components.Authorization;
var provider = new ControlledProvider();
var accessor = new ChangingAccessor(provider);
var resolver = new TenantConfigurationPrincipalResolver(new CircuitServicesAccessor(), accessor, provider);
var evidence = await resolver.ResolveAsync();
Console.WriteLine($"Resolver result: {evidence.State}; current administrator: {provider.Current.User.HasClaim("global_admin", "true")}");
sealed class ControlledProvider : AuthenticationStateProvider {
 public AuthenticationState Current { get; private set; } = new(new ClaimsPrincipal(new ClaimsIdentity([new Claim("sub", "same-subject"), new Claim("global_admin", "true"), new Claim("eventstore:tenant", "system")], "test")));
 public override Task<AuthenticationState> GetAuthenticationStateAsync() => Task.FromResult(Current);
 public void Revoke() { Current = new(new ClaimsPrincipal(new ClaimsIdentity([new Claim("sub", "same-subject"), new Claim("global_admin", "false"), new Claim("eventstore:tenant", "system")], "test"))); NotifyAuthenticationStateChanged(Task.FromResult(Current)); }
}
sealed class ChangingAccessor(ControlledProvider provider) : IUserContextAccessor { public string? UserId { get { provider.Revoke(); return "same-subject"; } } }

global using Microsoft.AspNetCore.Http;
namespace Hexalith.FrontComposer.Shell.Services.Auth { public sealed class CircuitServicesAccessor { public IServiceProvider? Services { get; set; } } }
namespace Hexalith.FrontComposer.Contracts.Rendering { public interface IUserContextAccessor { string? UserId { get; } } }
